// Selected Pexels clip: 8523251, native 30 fps; bounded decoded-frame cache.
(()=>{
const canvas=document.querySelector('#grillCanvas'),hero=document.querySelector('#hero'),button=document.querySelector('#mediaToggle'),ctx=canvas.getContext('2d',{alpha:false}),reduce=matchMedia('(prefers-reduced-motion: reduce)');
const total=190,cache=new Map(),pending=new Map();let paused=reduce.matches,target=0,current=0,drawn=-1,raf=0,last=0;
function draw(i){const img=cache.get(i);if(!img||i===drawn)return;const s=Math.max(canvas.width/img.width,canvas.height/img.height),w=img.width*s,h=img.height*s;ctx.drawImage(img,(canvas.width-w)/2,(canvas.height-h)/2,w,h);drawn=i;canvas.dataset.frame=String(i)}
function load(i){i=Math.max(0,Math.min(total-1,i));if(cache.has(i)||pending.has(i))return;const img=new Image();pending.set(i,img);img.onload=()=>{pending.delete(i);cache.set(i,img);if(i===Math.round(current))draw(i);for(const key of cache.keys())if(cache.size>28&&Math.abs(key-current)>14)cache.delete(key)};img.onerror=()=>pending.delete(i);img.src=`assets/selected-frames/frame-${String(i+1).padStart(3,'0')}.jpg`}
function tick(now){raf=0;const dt=last?Math.min(50,now-last):16;last=now;if(!paused){const d=target-current;current=Math.abs(d)<.03?target:current+d*(1-Math.exp(-dt/95))}const i=Math.round(current);draw(i);load(i);const direction=target>=current?1:-1;for(let n=1;n<=6;n++){load(i+n*direction);if(n<3)load(i-n*direction)}if(!paused&&Math.abs(target-current)>.03)raf=requestAnimationFrame(tick);else last=0}
function update(){if(!paused)target=Math.max(0,Math.min(1,-hero.getBoundingClientRect().top/Math.max(1,hero.offsetHeight-innerHeight)))*(total-1);if(!raf)raf=requestAnimationFrame(tick)}
function resize(){const r=canvas.getBoundingClientRect(),s=Math.min(devicePixelRatio||1,1.3,1280/Math.max(1,r.width));canvas.width=Math.round(r.width*s);canvas.height=Math.round(r.height*s);drawn=-1;draw(Math.round(current));update()}
function label(){if(!button)return;button.textContent=paused?'Включить анимацию':'Остановить анимацию';button.setAttribute('aria-pressed',String(paused))}
button?.addEventListener('click',()=>{paused=!paused;if(paused)target=current;label();update()});reduce.addEventListener('change',e=>{paused=e.matches;if(paused)target=current;label();update()});addEventListener('scroll',update,{passive:true});addEventListener('resize',resize);resize();label();load(0);
})();
